python3 - <<'EOF'
import os
root='/challenge/inhere'
for dirpath,_,files in os.walk(root):
    for fn in sorted(files):
        p=os.path.join(dirpath,fn)
        data=open(p,'rb').read()
        area=dirpath.split('area')[1].split('/')[0]
        item=fn.replace('item','')
        if item=='00':
            exp=b'\x00'*1033
        elif item=='01':
            exp=b'x'*1033
        else:
            exp=(f"record {area}-{item}\n".encode()*300)[:len(data)]
        if data!=exp:
            print("DIFFERS:",p,len(data))
            # show first difference
            for i,(a,b) in enumerate(zip(data,exp)):
                if a!=b:
                    print(" first diff at",i,data[max(0,i-20):i+80])
                    break
            else:
                print(" length diff only")
print("scan complete")
EOF

